from pathlib import Path

WORKFLOW = Path('.github/workflows/aws-platform-dr.yml')
text = WORKFLOW.read_text(encoding='utf-8')

# Scheduler/runtime implementation changes must not redeploy the independent platform DR stack.
old_ignore = """      - '.github/workflows/aws-staged-scheduler-runtime.yml'\n      - 'infra/aws/edge-runtime/staged-schedules.json'\n"""
new_ignore = """      - '.github/workflows/aws-staged-scheduler-runtime.yml'\n      - 'infra/aws/edge-runtime/**'\n"""
if old_ignore not in text:
    raise SystemExit('platform DR paths-ignore anchor not found')
text = text.replace(old_ignore, new_ignore, 1)

old_env = """  APP_ENV_SECRET_NAME: /theouthaven/production/platform-dr/app-env\n  CERT_PARAMETER: /theouthaven/production/platform-dr/acm-certificate-arn\n"""
new_env = """  APP_ENV_SECRET_NAME: /theouthaven/production/platform-dr/app-env\n  CERT_PARAMETER: /theouthaven/production/platform-dr/acm-certificate-arn\n  VIRGINIA_SUPABASE_REF: ftdsltatyqhtllyyefzp\n  VIRGINIA_SUPABASE_URL: https://ftdsltatyqhtllyyefzp.supabase.co\n"""
if old_env not in text:
    raise SystemExit('platform DR env anchor not found')
text = text.replace(old_env, new_env, 1)

old_pull = """      - name: Pull the production Vercel environment safely\n        env:\n          VERCEL_TOKEN: ${{ secrets.VERCEL_TOKEN }}\n          GATEWAY_URL: ${{ steps.compute.outputs.gateway_url }}\n        run: |\n          set -euo pipefail\n          test -n \"${VERCEL_TOKEN:-}\" || { echo \"VERCEL_TOKEN is required for the production standby sync.\" >&2; exit 1; }\n          mkdir -p .vercel\n          jq -n --arg org \"$VERCEL_TEAM_ID\" --arg project \"$VERCEL_PROJECT_ID\" '{orgId:$org,projectId:$project}' > .vercel/project.json\n          npx --yes vercel@59.3.0 env pull \"$RUNNER_TEMP/vercel-production.env\" --environment=production --yes --token \"$VERCEL_TOKEN\"\n          python -m pip install --disable-pip-version-check python-dotenv\n          GATEWAY_SECRET=\"$(cat \"$RUNNER_TEMP/platform-dr-gateway-secret\")\"\n          echo \"::add-mask::$GATEWAY_SECRET\"\n          ENV_FILE=\"$RUNNER_TEMP/vercel-production.env\" \\\n          JSON_FILE=\"$RUNNER_TEMP/platform-dr-app-env.json\" \\\n          BUILD_ENV=\"$RUNNER_TEMP/platform-dr-build.env\" \\\n          GATEWAY_URL=\"$GATEWAY_URL\" \\\n          GATEWAY_SECRET=\"$GATEWAY_SECRET\" \\\n          python - <<'PY'\n          import json, os, re\n          from dotenv import dotenv_values\n          values = {k: v for k, v in dotenv_values(os.environ['ENV_FILE']).items() if v is not None}\n          values['AWS_PLATFORM_DR_GATEWAY_URL'] = os.environ['GATEWAY_URL']\n          values['AWS_PLATFORM_DR_GATEWAY_SECRET'] = os.environ['GATEWAY_SECRET']\n          required = ['NEXT_PUBLIC_SUPABASE_URL','NEXT_PUBLIC_SUPABASE_ANON_KEY','SUPABASE_SERVICE_ROLE_KEY']\n          missing = [key for key in required if not values.get(key)]\n          if missing:\n              raise SystemExit('Missing required production environment values: ' + ', '.join(missing))\n          invalid = [key for key in values if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key)]\n          if invalid:\n              raise SystemExit('Unsupported environment key(s): ' + ', '.join(sorted(invalid)))\n          encoded = json.dumps(values, separators=(',', ':'))\n          if len(encoded.encode()) > 60000:\n              raise SystemExit('Production environment is too large for the single Secrets Manager JSON document.')\n          with open(os.environ['JSON_FILE'], 'w') as handle:\n              handle.write(encoded)\n          with open(os.environ['BUILD_ENV'], 'w') as handle:\n              for key in sorted(values):\n                  handle.write(f\"{key}={json.dumps(values[key])}\\n\")\n          PY\n          chmod 600 \"$RUNNER_TEMP/platform-dr-app-env.json\" \"$RUNNER_TEMP/platform-dr-build.env\"\n"""

new_pull = """      - name: Pull production environment and pin Virginia Supabase credentials\n        env:\n          VERCEL_TOKEN: ${{ secrets.VERCEL_TOKEN }}\n          SUPABASE_ACCESS_TOKEN: ${{ secrets.SUPABASE_ACCESS_TOKEN }}\n          GATEWAY_URL: ${{ steps.compute.outputs.gateway_url }}\n        run: |\n          set -euo pipefail\n          test -n \"${VERCEL_TOKEN:-}\" || { echo \"VERCEL_TOKEN is required for the production standby sync.\" >&2; exit 1; }\n          test -n \"${SUPABASE_ACCESS_TOKEN:-}\" || { echo \"SUPABASE_ACCESS_TOKEN is required to resolve the Virginia service credential.\" >&2; exit 1; }\n          mkdir -p .vercel\n          jq -n --arg org \"$VERCEL_ORG_ID\" --arg project \"$VERCEL_PROJECT_ID\" '{orgId:$org,projectId:$project}' > .vercel/project.json\n          npx --yes vercel@59.3.0 env pull \"$RUNNER_TEMP/vercel-production.env\" --environment=production --yes --token \"$VERCEL_TOKEN\" >/dev/null\n          python -m pip install --disable-pip-version-check python-dotenv\n\n          curl --fail --silent --show-error \\\n            --header \"Authorization: Bearer $SUPABASE_ACCESS_TOKEN\" \\\n            \"https://api.supabase.com/v1/projects/${VIRGINIA_SUPABASE_REF}/api-keys?reveal=true\" \\\n            > \"$RUNNER_TEMP/virginia-api-keys.json\"\n          VIRGINIA_SERVICE_ROLE=\"$(jq -r '[.[] | select(.type==\"legacy\" and .name==\"service_role\" and (.disabled != true))][0].api_key // empty' \"$RUNNER_TEMP/virginia-api-keys.json\")\"\n          test -n \"$VIRGINIA_SERVICE_ROLE\" || { echo \"Virginia service-role credential unavailable.\" >&2; exit 1; }\n          echo \"::add-mask::$VIRGINIA_SERVICE_ROLE\"\n          printf '%s' \"$VIRGINIA_SERVICE_ROLE\" > \"$RUNNER_TEMP/virginia-service-role\"\n          chmod 600 \"$RUNNER_TEMP/virginia-service-role\"\n          rm -f \"$RUNNER_TEMP/virginia-api-keys.json\"\n\n          SUPABASE_STATUS=\"$(curl --silent --show-error --output /dev/null --write-out '%{http_code}' \\\n            --header \"apikey: $VIRGINIA_SERVICE_ROLE\" \\\n            --header \"Authorization: Bearer $VIRGINIA_SERVICE_ROLE\" \\\n            \"${VIRGINIA_SUPABASE_URL}/rest/v1/cron_jobs?select=job_key&limit=1\")\"\n          test \"$SUPABASE_STATUS\" = '200' || { echo \"Virginia service-role validation failed: HTTP $SUPABASE_STATUS\" >&2; exit 1; }\n\n          GATEWAY_SECRET=\"$(cat \"$RUNNER_TEMP/platform-dr-gateway-secret\")\"\n          echo \"::add-mask::$GATEWAY_SECRET\"\n          ENV_FILE=\"$RUNNER_TEMP/vercel-production.env\" \\\n          KEY_FILE=\"$RUNNER_TEMP/virginia-service-role\" \\\n          JSON_FILE=\"$RUNNER_TEMP/platform-dr-app-env.json\" \\\n          BUILD_ENV=\"$RUNNER_TEMP/platform-dr-build.env\" \\\n          GATEWAY_URL=\"$GATEWAY_URL\" \\\n          GATEWAY_SECRET=\"$GATEWAY_SECRET\" \\\n          VIRGINIA_SUPABASE_URL=\"$VIRGINIA_SUPABASE_URL\" \\\n          python - <<'PY'\n          import json, os, re\n          from dotenv import dotenv_values\n          values = {k: v for k, v in dotenv_values(os.environ['ENV_FILE']).items() if v is not None}\n          with open(os.environ['KEY_FILE'], encoding='utf-8') as handle:\n              service_role = handle.read().strip()\n          if not service_role:\n              raise SystemExit('Validated Virginia service-role credential is empty.')\n          values['NEXT_PUBLIC_SUPABASE_URL'] = os.environ['VIRGINIA_SUPABASE_URL']\n          values['SUPABASE_SERVICE_ROLE_KEY'] = service_role\n          values['AWS_PLATFORM_DR_GATEWAY_URL'] = os.environ['GATEWAY_URL']\n          values['AWS_PLATFORM_DR_GATEWAY_SECRET'] = os.environ['GATEWAY_SECRET']\n          required = ['NEXT_PUBLIC_SUPABASE_URL','NEXT_PUBLIC_SUPABASE_ANON_KEY','SUPABASE_SERVICE_ROLE_KEY']\n          missing = [key for key in required if not values.get(key)]\n          if missing:\n              raise SystemExit('Missing required production environment values: ' + ', '.join(missing))\n          invalid = [key for key in values if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key)]\n          if invalid:\n              raise SystemExit('Unsupported environment key(s): ' + ', '.join(sorted(invalid)))\n          encoded = json.dumps(values, separators=(',', ':'))\n          if len(encoded.encode()) > 60000:\n              raise SystemExit('Production environment is too large for the single Secrets Manager JSON document.')\n          with open(os.environ['JSON_FILE'], 'w') as handle:\n              handle.write(encoded)\n          with open(os.environ['BUILD_ENV'], 'w') as handle:\n              for key in sorted(values):\n                  handle.write(f\"{key}={json.dumps(values[key])}\\n\")\n          PY\n          rm -f \"$RUNNER_TEMP/virginia-service-role\"\n          chmod 600 \"$RUNNER_TEMP/platform-dr-app-env.json\" \"$RUNNER_TEMP/platform-dr-build.env\"\n"""

if old_pull not in text:
    raise SystemExit('platform DR Vercel environment block not found')
text = text.replace(old_pull, new_pull, 1)

# Add a static guard so future edits cannot silently restore Vercel as service-key authority.
needle = """      - name: Run focused DR contract tests\n        run: |\n          set -euo pipefail\n          npm ci\n          npx vitest run lib/__tests__/platform-dr-contract.test.ts\n"""
guard = needle + """\n      - name: Validate Virginia Supabase credential authority\n        run: |\n          set -euo pipefail\n          FILE='.github/workflows/aws-platform-dr.yml'\n          grep -F 'VIRGINIA_SUPABASE_REF: ftdsltatyqhtllyyefzp' \"$FILE\" >/dev/null\n          grep -F 'api-keys?reveal=true' \"$FILE\" >/dev/null\n          grep -F '.name==\"service_role\"' \"$FILE\" >/dev/null\n          grep -F \"values['SUPABASE_SERVICE_ROLE_KEY'] = service_role\" \"$FILE\" >/dev/null\n          grep -F \"values['NEXT_PUBLIC_SUPABASE_URL'] = os.environ['VIRGINIA_SUPABASE_URL']\" \"$FILE\" >/dev/null\n          grep -F \"SUPABASE_STATUS\" \"$FILE\" >/dev/null\n          grep -F \"- 'infra/aws/edge-runtime/**'\" \"$FILE\" >/dev/null\n"""
if needle not in text:
    raise SystemExit('platform DR validation anchor not found')
text = text.replace(needle, guard, 1)

WORKFLOW.write_text(text, encoding='utf-8')
print('patched platform DR Virginia credential authority')
